"""The repository gate refuses tracked generated bytecode artifacts.

The .gitignore names __pycache__/ and *.py[cod], but ignore rules do not
stop a forced add, and the validator's source walk pruned __pycache__
before looking, so a tree carrying compiled bytecode passed every check.
These tests pin the guard both ways: a planted artifact fails validation
and a clean fixture tree passes it.
"""
import importlib.util
import json
from pathlib import Path
import tempfile
import unittest

TOOLS = next(p / "tools" for p in Path(__file__).resolve().parents if (p / "tools/validate_repo.py").is_file())
spec = importlib.util.spec_from_file_location("validate_repo", TOOLS / "validate_repo.py")
validator = importlib.util.module_from_spec(spec)
spec.loader.exec_module(validator)

ROOT = TOOLS.parent


FIXTURE_SKILLS = (
    # The core skill's recorded relations, closed transitively: discover()
    # refuses a registry whose related skills are absent, so the fixture
    # carries the whole closure with placeholder bodies.
    "infinityblade", "efficiency-breakthroughs", "proof-before-green",
    "memory-recall-systems", "gate-test-integrity", "live-execution-proof",
    "save-readback-verification", "stable-tree-gate-integrity",
    "hermetic-test-isolation",
)


def build_fixture(base):
    """A minimal tree that passes validation on its own merits."""
    repo = Path(base) / "repo"
    (repo / "PRIMER.md").parent.mkdir(parents=True, exist_ok=True)
    (repo / "PRIMER.md").write_text("# Fixture primer\n", encoding="utf-8")
    for name in FIXTURE_SKILLS:
        skill = repo / "skills" / name
        skill.mkdir(parents=True)
        (skill / "SKILL.md").write_text(
            f"---\nname: {name}\ndescription: Fixture skill for gate tests.\n---\n\n# Fixture\n",
            encoding="utf-8")
    (repo / "skills" / "runtime-dependencies.json").write_text(
        json.dumps({"schema_version": 1, "skills": {}}), encoding="utf-8")
    tools = repo / "tools"
    tools.mkdir()
    (tools / "fixture_tool.py").write_text("VALUE = 1\n", encoding="utf-8")
    registry = validator.discover(repo)
    (repo / "skills" / "registry.json").write_text(
        json.dumps(registry, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return repo


class GeneratedArtifactGuardTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.repo = build_fixture(self.temp.name)

    def test_clean_fixture_tree_passes_validation(self):
        result = validator.validate(self.repo)
        self.assertTrue(result["passed"], result["errors"])
        self.assertEqual(validator.generated_artifact_errors(self.repo), [])

    def test_bytecode_under_pycache_fails_validation(self):
        cache = self.repo / "skills" / "infinityblade" / "bin" / "__pycache__"
        cache.mkdir(parents=True)
        (cache / "module.cpython-312.pyc").write_bytes(b"\x42\x0d\x0d\x0a")
        found = validator.generated_artifact_errors(self.repo)
        self.assertEqual([row["path"] for row in found],
                         ["skills/infinityblade/bin/__pycache__/module.cpython-312.pyc"])
        result = validator.validate(self.repo)
        self.assertFalse(result["passed"])
        kinds = [row["kind"] for row in result["errors"]]
        self.assertIn("generated_artifact", kinds)

    def test_bytecode_suffix_outside_pycache_is_flagged(self):
        for name in ("stray.pyc", "stray.pyo", "stray.pyd"):
            with self.subTest(name=name):
                target = self.repo / "tools" / name
                target.write_bytes(b"\x42\x0d\x0d\x0a")
                found = validator.generated_artifact_errors(self.repo)
                self.assertEqual([row["path"] for row in found], [f"tools/{name}"])
                target.unlink()

    def test_plain_sources_and_docs_are_not_flagged(self):
        (self.repo / "tools" / "notes.md").write_text("# Notes\n", encoding="utf-8")
        (self.repo / "tools" / "data.json").write_text("{}\n", encoding="utf-8")
        self.assertEqual(validator.generated_artifact_errors(self.repo), [])


if __name__ == "__main__":
    unittest.main()
